          ),
        ),
      ),
    );
  }
}

class _DocumentThumbnail extends StatelessWidget {
  const _DocumentThumbnail({
    required this.repository,
    required this.document,
    required this.canManage,
    required this.onOpen,
    this.onPrimary,
    this.onDelete,
  });

  final FinancialDocumentsRepository repository;
  final Map<String, dynamic> document;
  final bool canManage;
  final VoidCallback onOpen;
  final VoidCallback? onPrimary;
  final VoidCallback? onDelete;

  @override
  Widget build(BuildContext context) {
    final primary = document['is_primary'] == true;
    final image = FinancialDocumentsRepository.isImage(document);

    return SizedBox(
      width: 112,
      child: Card(
        clipBehavior: Clip.antiAlias,
        child: Stack(
          fit: StackFit.expand,
          children: [
            InkWell(
              onTap: onOpen,
              child: image
                  ? FutureBuilder<String>(
                      future: repository.signedUrl(document),
                      builder: (context, snapshot) {
                        if (!snapshot.hasData) {
                          return const Center(
                            child: CircularProgressIndicator(strokeWidth: 2),
                          );
                        }
                        return Image.network(snapshot.data!, fit: BoxFit.cover);
                      },
                    )
                  : Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(
                          FinancialDocumentsRepository.isPdf(document)
                              ? Icons.picture_as_pdf_outlined
                              : Icons.description_outlined,
                          size: 34,
                        ),
                        const SizedBox(height: 4),
                        Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 5),
                          child: Text(
                            FinancialDocumentsRepository.documentTypeLabel(
                              document['document_type']?.toString(),
                            ),
                            textAlign: TextAlign.center,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: Theme.of(context).textTheme.labelSmall,
                          ),
                        ),
                      ],
                    ),
            ),
            if (primary)
              const Positioned(
                left: 4,
                bottom: 4,
                child: Icon(Icons.star, size: 20),
              ),
            if (document['origin'] == 'request')
              const Positioned(
                left: 4,
                top: 4,
                child: Tooltip(
                  message: 'Herdado do pedido financeiro',
                  child: Icon(Icons.link, size: 20),
                ),
              ),
            if (canManage && (onPrimary != null || onDelete != null))
              Positioned(
                right: 0,
                top: 0,
                child: PopupMenuButton<String>(
                  iconSize: 20,
                  padding: EdgeInsets.zero,
                  onSelected: (value) {
                    if (value == 'primary') onPrimary?.call();
                    if (value == 'delete') onDelete?.call();
                  },
                  itemBuilder: (_) => [
                    if (onPrimary != null)
                      const PopupMenuItem(
                        value: 'primary',
                        child: Text('Definir como principal'),
                      ),
                    if (onDelete != null)
                      const PopupMenuItem(
                        value: 'delete',
                        child: Text('Eliminar documento'),
                      ),
                  ],
                ),
              ),
          ],
        ),
      ),
    );
  }
}
", 'apps/mobile/lib/screens/financial_transaction_documents_screen.dart': "import 'package:flutter/material.dart';

import '../repositories/financial_documents_repository.dart';
import '../widgets/financial_document_gallery.dart';

class FinancialTransactionDocumentsScreen extends StatelessWidget {
  const FinancialTransactionDocumentsScreen({
    super.key,
    required this.transaction,
    this.onChanged,
  });

  final Map<String, dynamic> transaction;
  final Future<void> Function()? onChanged;

  @override
  Widget build(BuildContext context) {
    final repository = FinancialDocumentsRepository();
    final transactionId = transaction['id']?.toString() ?? '';
    final kind = transaction['kind']?.toString();
    final isIncome = kind == 'income';
    final isTransfer = kind == 'transfer';

    return Scaffold(
      appBar: AppBar(
        title: const Text('Documentos do movimento'),
      ),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 48),
        children: [
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      CircleAvatar(
                        child: Icon(
                          isTransfer
                              ? Icons.swap_horiz
                              : isIncome
                                  ? Icons.arrow_downward
                                  : Icons.arrow_upward,
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              transaction['description']?.toString() ??
                                  'Movimento',
                              style: Theme.of(context)
                                  .textTheme
                                  .titleLarge
                                  ?.copyWith(fontWeight: FontWeight.w900),
                            ),
                            const SizedBox(height: 3),
                            Text(
                              [
                                transaction['transaction_date']?.toString(),
                                transaction['account_name']?.toString(),
                                transaction['cost_center_name']?.toString(),
                              ]
                                  .where((value) =>
                                      value != null && value.trim().isNotEmpty)
                                  .join(' • '),
                            ),
                          ],
                        ),
                      ),
                      Text(
                        '${isIncome ? '+' : isTransfer ? '' : '-'}${_money(transaction['amount'])}',
                        style: Theme.of(context)
                            .textTheme
                            .titleLarge
                            ?.copyWith(fontWeight: FontWeight.w900),
                      ),
                    ],
                  ),
                  if ((transaction['payment_method']?.toString() ?? '')
                      .isNotEmpty) ...[
                    const SizedBox(height: 10),
                    Text(
                      'Pagamento: ${_paymentMethod(transaction['payment_method']?.toString())}',
                    ),
                  ],
                  if ((transaction['notes']?.toString() ?? '').isNotEmpty) ...[
                    const SizedBox(height: 8),
                    Text(transaction['notes'].toString()),
                  ],
                ],
              ),
            ),
          ),
          const SizedBox(height: 16),
          if (transactionId.isEmpty)
            const Card(
              child: ListTile(
                leading: Icon(Icons.error_outline),
                title: Text('Movimento sem identificador.'),
              ),
            )
          else
            FinancialDocumentGallery(
              repository: repository,
              transactionId: transactionId,
              canManage: repository.canManage,
              onChanged: onChanged,
            ),
          const SizedBox(height: 16),
          Card(
            child: ListTile(
              leading: const Icon(Icons.verified_user_outlined),
              title: const Text('Arquivo financeiro auditado'),
              subtitle: const Text(
                'Cada ficheiro fica associado individualmente ao movimento. '
                'Talões e comprovativos herdados de pedidos financeiros são '
                'mantidos como evidência e não são duplicados no Storage.',
              ),
            ),
          ),
        ],
      ),
    );
  }

  static String _money(Object? value) {
    final amount = value is num
        ? value.toDouble()
        : double.tryParse(value?.toString() ?? '') ?? 0;
    return '${amount.toStringAsFixed(2).replaceAll('.', ',')} €';
  }

  static String _paymentMethod(String? value) {
    if (value == null || value.isEmpty) return '—';
    return switch (value) {
      'cash' => 'Numerário',
      'mbway' => 'MB Way',
      'bank_transfer' => 'Transferência bancária',
      'other' => 'Outro',
      _ => value,
    };
  }
}
