-- 7) Mantém compatibilidade com chamadas antigas a audit_event.
create or replace function public.audit_event(
  target_club uuid,
  p_action text,
  p_entity_type text,
  p_entity_id text,
  p_old jsonb default null,
  p_new jsonb default null,
