                  maxLines: 4,
                  decoration: const InputDecoration(labelText: 'Mensagem (opcional)'),
                ),
                const SizedBox(height: 8),
                const Text(
                  'A troca só altera a escala depois de ser aceite e validada pela Direção.',
                ),
              ],
            ),
          ),
