FILES = {'apps/mobile/lib/core/agenda_rules.dart': "class AgendaRules {
  const AgendaRules._();

  static const Map<String, String> filterLabels = {
    'all': 'Tudo',
    'meetings': 'Reuniões',
    'events': 'Eventos',
    'birthdays': 'Aniversários',
    'milestones': 'Marcos',
    'dinners': 'Jantares',
    'deadlines': 'Prazos',
    'charges': 'Cobranças',
  };

  static DateTime monthStart(DateTime value) =>
      DateTime(value.year, value.month, 1);

  static DateTime monthEnd(DateTime value) =>
      DateTime(value.year, value.month + 1, 0);

  static List<DateTime> monthGrid(DateTime month) {
    final first = monthStart(month);
    final start = first.subtract(Duration(days: first.weekday - DateTime.monday));
    return List<DateTime>.generate(
      42,
      (index) => DateTime(start.year, start.month, start.day + index),
      growable: false,
    );
  }

  static bool sameDay(DateTime a, DateTime b) =>
      a.year == b.year && a.month == b.month && a.day == b.day;

  static bool inMonth(DateTime day, DateTime month) =>
      day.year == month.year && day.month == month.month;

  static DateTime rowDate(Map<String, dynamic> row) {
    final raw = row['starts_at']?.toString() ?? '';
    return DateTime.parse(raw).toLocal();
  }

  static bool matchesFilter(Map<String, dynamic> row, String filter) {
    if (filter == 'all') return true;
    final source = row['source_type']?.toString() ?? '';
    final kind = row['item_kind']?.toString() ?? '';

    return switch (filter) {
      'meetings' => source == 'agenda' && kind == 'meeting',
      'events' => source == 'event',
      'birthdays' => source == 'member' && kind == 'birthday',
      'milestones' =>
        source == 'member' && (kind == 'prospect' || kind == 'full_colors'),
      'dinners' => source == 'weekly_dinner',
      'deadlines' =>
        source == 'document' ||
            (source == 'agenda' &&
                (kind == 'deadline' || kind == 'reminder')),
      'charges' => source == 'fee',
      _ => true,
    };
  }

  static String kindLabel(Map<String, dynamic> row) {
    final source = row['source_type']?.toString() ?? '';
    final kind = row['item_kind']?.toString() ?? '';

    if (source == 'event') return 'Evento';
    if (source == 'weekly_dinner') {
      return kind == 'dinner_extraordinary'
          ? 'Jantar extraordinário'
          : 'Jantar';
    }
    if (source == 'document') return 'Prazo';
    if (source == 'fee') return 'Cobrança';
    if (source == 'member') {
      return switch (kind) {
        'birthday' => 'Aniversário',
        'prospect' => 'Prospect',
        'full_colors' => 'Full Colors',
        _ => 'Membro',
      };
    }
    return switch (kind) {
      'meeting' => 'Reunião',
      'deadline' => 'Prazo',
      'reminder' => 'Lembrete',
      _ => 'Agenda',
    };
  }

  static bool isHighPriority(Map<String, dynamic> row) =>
      row['priority']?.toString() == 'high' ||
      row['item_status']?.toString() == 'overdue';
}
", 'apps/mobile/lib/repositories/agenda_repository.dart': "import 'package:supabase_flutter/supabase_flutter.dart';

import '../core/app_config.dart';
import '../core/app_session.dart';

class AgendaRepository {
  AgendaRepository({SupabaseClient? client}) : _client = client;

  final SupabaseClient? _client;

  SupabaseClient get _supabase => _client ?? Supabase.instance.client;
  String get _clubId => AppSession.instance.clubId;

  Future<bool> canManage() async {
    if (AppConfig.demoMode) return AppSession.instance.superAdmin;
    final response = await _supabase.rpc(
      'can_manage_agenda_v1',
      params: {'target_club': _clubId},
    );
    return response == true || response?.toString().toLowerCase() == 'true';
  }

  Future<void> ensureDinnerYears(DateTime from, DateTime to) async {
    if (AppConfig.demoMode) return;
    for (var year = from.year; year <= to.year; year++) {
      await _supabase.rpc(
        'ensure_weekly_officer_schedule_v1',
        params: {'target_club': _clubId, 'p_year': year},
      );
    }
  }

  Future<List<Map<String, dynamic>>> calendar(
    DateTime from,
    DateTime to,
  ) async {
    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];
    final response = await _supabase.rpc(
      'agenda_calendar_v1',
      params: {
        'target_club': _clubId,
        'p_from': _date(from),
        'p_to': _date(to),
      },
    );
    return List<Map<String, dynamic>>.from(response as List);
  }

  Future<Map<String, dynamic>?> manualItem(String itemId) async {
    if (AppConfig.demoMode) return null;
    final response = await _supabase
        .from('agenda_items')
        .select()
        .eq('club_id', _clubId)
        .eq('id', itemId)
        .maybeSingle();
    return response;
  }

  Future<String> saveManualItem({
    String? itemId,
    required String itemType,
    required String title,
    String? description,
    required DateTime startsAt,
    DateTime? endsAt,
    required bool allDay,
    String? location,
    required String audience,
    required String priority,
    required String status,
    bool notifyNow = false,
  }) async {
    final response = await _supabase.rpc(
      'save_agenda_item_v1',
      params: {
        'target_club': _clubId,
        'p_item': _emptyToNull(itemId),
        'p_item_type': itemType,
        'p_title': title.trim(),
        'p_description': _emptyToNull(description),
        'p_starts_at': startsAt.toUtc().toIso8601String(),
        'p_ends_at': endsAt?.toUtc().toIso8601String(),
        'p_all_day': allDay,
        'p_location': _emptyToNull(location),
        'p_audience': audience,
        'p_priority': priority,
        'p_status': status,
        'p_notify_now': notifyNow,
      },
    );
    return response.toString();
  }

  Future<void> cancelManualItem(String itemId, {String? reason}) async {
    await _supabase.rpc(
      'cancel_agenda_item_v1',
      params: {
        'target_club': _clubId,
        'p_item': itemId,
        'p_reason': _emptyToNull(reason),
      },
    );
  }

  static String _date(DateTime value) =>
      '${value.year.toString().padLeft(4, '0')}-'
      '${value.month.toString().padLeft(2, '0')}-'
      '${value.day.toString().padLeft(2, '0')}';

  static String? _emptyToNull(String? value) {
    final text = value?.trim() ?? '';
    return text.isEmpty ? null : text;
  }
}
