    expect(
      AgendaRules.matchesFilter(
        {'source_type': 'member', 'item_kind': 'birthday'},
        'birthdays',
      ),
      isTrue,
    );
    expect(
      AgendaRules.matchesFilter(
        {'source_type': 'member', 'item_kind': 'full_colors'},
        'birthdays',
      ),
      isFalse,
    );
  });

  test('filtro de prazos inclui documentos e prazos manuais', () {
    expect(
      AgendaRules.matchesFilter(
        {'source_type': 'document', 'item_kind': 'deadline'},
